class Solution:
    def isPalindrome(self, x: int) -> bool:
        s = str(x)
        return s == s[::-1]

solutions.better:
class Solution:
    def isPalindrome(self, x: int) -> bool:
        if x < 0:
            return False
        original, rev = x, 0
        while x:
            rev = rev * 10 + x % 10
            x //= 10
        return rev == original

solutions.optimal:
class Solution:
    def isPalindrome(self, x: int) -> bool:
        if x < 0 or (x % 10 == 0 and x != 0):
            return False
        rev_half = 0
        while x > rev_half:
            rev_half = rev_half * 10 + x % 10
            x //= 10
        # For odd digit counts, drop the middle digit from rev_half.
        return x == rev_half or x == rev_half // 10

